require "download_strategy"
require "json"
require "utils/curl"

class SandyGitHubPrivateRepositoryReleaseDownloadStrategy < CurlDownloadStrategy
  def initialize(url, name, version, **meta)
    super
    match = url.match(%r{^https://github\.com/([^/]+)/([^/]+)/releases/download/([^/]+)/(.+)$})
    raise CurlDownloadStrategyError, "unexpected release URL: #{url}" unless match

    @owner, @repo, @tag, @asset_name = match.captures
    @token = ENV["HOMEBREW_GITHUB_API_TOKEN"].to_s.strip
    odie <<~EOS if @token.empty?
      HOMEBREW_GITHUB_API_TOKEN is required while Sandy is distributed privately.

      Authenticate with GitHub CLI using an account with access to
      kontext-security/sandy, then retry:
        HOMEBREW_GITHUB_API_TOKEN="$(gh auth token)" brew install kontext-security/tap/sandy
    EOS
  end

  private

  def _fetch(url:, resolved_url:, timeout:)
    curl_download "https://api.github.com/repos/#{@owner}/#{@repo}/releases/assets/#{asset_id}",
                  "--header", "Accept: application/octet-stream",
                  "--header", "Authorization: Bearer #{@token}",
                  to: temporary_path, timeout: timeout
  end

  def asset_id
    release = JSON.parse(Utils::Curl.curl_output(
      "--fail", "--silent", "--location",
      "--header", "Accept: application/vnd.github+json",
      "--header", "Authorization: Bearer #{@token}",
      "https://api.github.com/repos/#{@owner}/#{@repo}/releases/tags/#{@tag}"
    ).stdout)
    asset = release.fetch("assets", []).find { |candidate| candidate["name"] == @asset_name }
    odie "asset #{@asset_name} not found on #{@owner}/#{@repo} release #{@tag}" unless asset

    asset["id"]
  end
end

